package com.bank.stock.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "stock")
public class Stock {
    @Id private String symbol;
    private String name;
    private int quantity;
    private BigDecimal price;
    @Version private Long version;   // optimistic

    protected Stock() {}
    public int getQuantity() { return quantity; }
    public String getSymbol() { return symbol; }

    public void reduce(int qty) {
        if (quantity < qty) throw new IllegalStateException("Out of stock: " + symbol);
        this.quantity -= qty;
    }
}
