package com.bank.stock.repository;

import com.bank.stock.model.Stock;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.Optional;

public interface StockRepository extends JpaRepository<Stock, String> {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Stock s where s.symbol = :sym")
    Optional<Stock> findForUpdate(@Param("sym") String sym);

    // atomic conditional decrement — no read-modify-write race
    @Modifying
    @Query("update Stock s set s.quantity = s.quantity - :q " +
           "where s.symbol = :sym and s.quantity >= :q")
    int tryDecrement(@Param("sym") String sym, @Param("q") int q);
}
