package com.bank.stock.service;

import com.bank.stock.model.Stock;
import com.bank.stock.repository.StockRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Slf4j
@Service
@RequiredArgsConstructor
public class StockService {
    private final StockRepository repo;

    // COLD symbol: optimistic with small retry
    public void buyOptimistic(String sym, int qty) {
        for (int attempt = 1; ; attempt++) {
            try { doBuyOptimistic(sym, qty); return; }
            catch (ObjectOptimisticLockingFailureException e) {
                if (attempt >= 3) throw e;
                log.warning(() -> "Conflict on " + sym + " retry " + attempt);
            }
        }
    }
    @Transactional
    protected void doBuyOptimistic(String sym, int qty) {
        Stock s = repo.findById(sym).orElseThrow();
        s.reduce(qty);  // UPDATE ... WHERE version=?
    }

    // HOT symbol: pessimistic, serialize buyers
    @Transactional
    public void buyPessimistic(String sym, int qty) {
        Stock s = repo.findForUpdate(sym).orElseThrow();  // FOR UPDATE
        s.reduce(qty);
        log.info("Pessimistic buy {} x{}", sym, qty);
    }

    // Bulletproof: atomic conditional decrement, no lock held in app
    @Transactional
    public boolean buyAtomic(String sym, int qty) {
        int updated = repo.tryDecrement(sym, qty);
            if (updated == 0) { log.warning(() -> "Oversell blocked: " + sym);
            return false; }
        return true;
    }
}
